'use client';
import { useEffect, useState } from 'react';
import { receivingApi, receivingError, show, type VendorOverview } from '../invoices/receiving-client';
import '../admin.css';
import '../costing.css';
import '../invoices/receiving.css';

const when = (value: string | null) => (value ? new Date(value).toLocaleDateString() : '—');

/** One place for a vendor: invoices, purchase orders, receiving, current product mappings, cost history, deals, and claims/credits. */
export default function VendorDetailPage(): React.ReactNode {
  const [id] = useState(() => (typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get('id') ?? ''));
  const [data, setData] = useState<VendorOverview | null>(null); const [error, setError] = useState('');
  useEffect(() => { if (!id) { setError('No vendor selected.'); return; } receivingApi.vendor(id).then(setData).catch((cause) => setError(receivingError(cause))); }, [id]);
  return <main className="admin-main costing-page">
    <header className="admin-heading"><div><a href="/admin/#Vendors">← Vendors</a><span className="eyebrow">Vendor</span><h1>{data?.vendor.name ?? 'Vendor'}</h1></div><div><a className="hdr-link" href="/admin/invoices/">Receive an invoice →</a></div></header>
    {error && <p className="admin-alert error" role="alert">{error}</p>}
    {data && <>
      <p className="hint">{[data.vendor.contactName, data.vendor.phone, data.vendor.email].filter(Boolean).join(' · ') || 'No contact details.'}</p>
      <dl className="calc"><div><dt>Invoices</dt><dd>{data.invoices.length}</dd></div><div><dt>Purchase orders</dt><dd>{data.purchaseOrders.length}</dd></div><div><dt>Products</dt><dd>{data.mappings.length}</dd></div><div><dt>Credits expected</dt><dd>{show(data.openCreditExpectedMinor)}</dd></div></dl>
      <section className="wizard-section" aria-label="Invoices"><h2>Invoices</h2><table className="line-table"><thead><tr><th>Invoice #</th><th>Date</th><th>Type</th><th>Status</th><th className="num">Total</th></tr></thead><tbody>{data.invoices.map((invoice) => <tr key={invoice.id}><td><a href="/admin/invoices/">{invoice.invoiceNumber ?? 'unnumbered'}</a></td><td>{when(invoice.invoiceDate ?? invoice.uploadedAt)}</td><td>{invoice.docType.replace(/_/g, ' ').toLowerCase()}</td><td>{invoice.reviewStatus.toLowerCase()}</td><td className="num">{show(invoice.totalMinor)}</td></tr>)}{data.invoices.length === 0 && <tr><td colSpan={5}>No invoices.</td></tr>}</tbody></table></section>
      <section className="wizard-section" aria-label="Purchase orders and receiving"><h2>Purchase orders and receiving</h2>
        <table className="line-table"><thead><tr><th>PO</th><th>Status</th><th>Created</th></tr></thead><tbody>{data.purchaseOrders.map((po) => <tr key={po.id}><td>{po.poNumber}</td><td>{po.status.toLowerCase().replace('_', ' ')}</td><td>{when(po.createdAt)}</td></tr>)}{data.purchaseOrders.length === 0 && <tr><td colSpan={3}>No purchase orders.</td></tr>}</tbody></table>
        <h3>Recent receipts</h3><table className="line-table"><tbody>{data.receipts.map((receipt) => <tr key={receipt.id}><td>{when(receipt.receivedAt)}</td><td>{receipt.vendorReferenceNumber ?? '—'}</td><td>{receipt.purchaseOrder.poNumber}</td></tr>)}{data.receipts.length === 0 && <tr><td colSpan={3}>No receipts.</td></tr>}</tbody></table><a href="/admin/receiving/">Search all receiving →</a></section>
      <section className="wizard-section" aria-label="Products"><h2>Products and current costs</h2><table className="line-table"><thead><tr><th>Product</th><th>Vendor SKU</th><th className="num">Pack</th><th className="num">Case cost</th><th className="num">Unit cost</th></tr></thead><tbody>{data.mappings.map((mapping) => <tr key={mapping.id}><td><a href={`/admin/product/?id=${mapping.variant.product.id}`}>{mapping.variant.product.name}</a>{mapping.preferred && <span className="pill"> preferred</span>}<small className="stack">{mapping.variant.name}</small></td><td>{mapping.vendorSku ?? '—'}</td><td className="num">{mapping.casePackQuantity}</td><td className="num">{show(mapping.caseCostMinor)}</td><td className="num">{show(mapping.vendorCostMinor)}</td></tr>)}{data.mappings.length === 0 && <tr><td colSpan={5}>No product mappings.</td></tr>}</tbody></table></section>
      <section className="wizard-section" aria-label="Cost history"><h2>Cost history (as purchased)</h2><table className="line-table"><thead><tr><th>Date</th><th>Product</th><th className="num">Base case</th><th className="num">Net case</th><th className="num">Effective case</th></tr></thead><tbody>{data.costHistory.map((row) => <tr key={row.id}><td>{when(row.occurredAt)}</td><td>{row.variant.product.name}<small className="stack">{row.variant.name}</small></td><td className="num">{show(row.baseCaseCostMinor)}</td><td className="num">{show(row.netCaseCostMinor)}</td><td className="num">{show(row.effectiveCaseCostMinor)}{row.temporaryDeal && <small className="stack rt-warn">deal price</small>}</td></tr>)}{data.costHistory.length === 0 && <tr><td colSpan={5}>No purchases recorded.</td></tr>}</tbody></table></section>
      <section className="wizard-section" aria-label="Deals"><h2>Deals and rebates</h2>{data.deals.length ? <ul>{data.deals.map((deal) => <li key={deal.id}>{deal.name} · {deal.kind.replace(/_/g, ' ').toLowerCase()}{deal.amountMinor ? ` · ${show(deal.amountMinor)}` : ''}</li>)}</ul> : <p className="hint">No active deals.</p>}</section>
      <section className="wizard-section" aria-label="Claims and credits"><h2>Claims and credits</h2><table className="line-table"><thead><tr><th>Date</th><th>Type</th><th>Status</th><th>Reason</th><th className="num">Expected</th><th className="num">Credited</th><th>Credit #</th></tr></thead><tbody>{data.claims.map((claim) => <tr key={claim.id}><td>{when(claim.createdAt)}</td><td>{claim.kind.replace(/_/g, ' ').toLowerCase()}</td><td>{claim.status.toLowerCase()}{claim.resolvedAt ? ` ${when(claim.resolvedAt)}` : ''}</td><td>{claim.reason}</td><td className="num">{show(claim.expectedCreditMinor)}</td><td className="num">{show(claim.creditedMinor)}</td><td>{claim.creditReference ?? ''}</td></tr>)}{data.claims.length === 0 && <tr><td colSpan={7}>No claims.</td></tr>}</tbody></table><a href="/admin/claims/">Manage claims →</a></section></>}
  </main>;
}
